    int row = blockRow * BLOCK_SIZE + threadIdx.y;
    int col = blockCol * BLOCK_SIZE + threadIdx.x;

    // Shared memory for A_sub and B_sub
    __shared__ float A_shared[BLOCK_SIZE][BLOCK_SIZE];
    __shared__ float B_shared[BLOCK_SIZE][BLOCK_SIZE];

    float C_value = 0.0f;

    // Loop over tiles
    int numTiles = (N + BLOCK_SIZE - 1) / BLOCK_SIZE;
    for (int t = 0; t < numTiles; ++t) {
        // Load tiles into shared memory
        int A_row = blockRow * BLOCK_SIZE + threadIdx.y;
        int A_col = t * BLOCK_SIZE + threadIdx.x;
        if (A_row < N && A_col < N) {
            A_shared[threadIdx.y][threadIdx.x] = A[A_row * N + A_col];
        } else {
