    int numTiles = (N + BLOCK_SIZE - 1) / BLOCK_SIZE;
    for (int t = 0; t < numTiles; ++t) {
        // Load A tile into shared memory with vectorized loads
        int A_row_global = blockRow * BLOCK_SIZE + threadIdx.y;
        int A_col_global_base = t * BLOCK_SIZE;

        if (A_row_global < N) {
            // Each thread loads 4 elements for A
            // Ensure the start address for float4 is within bounds and aligned
            int A_load_col_start = A_col_global_base + threadIdx.x * 4;

            // Check if the entire float4 load is within bounds
            if (A_load_col_start + 3 < N) {
                float4 a_vec = *(reinterpret_cast<const float4*>(A + A_row_global * N + A_load_col_start));
                A_shared[threadIdx.y][threadIdx.x * 4] = a_vec.x;
                A_shared[threadIdx.y][threadIdx.x * 4 + 1] = a_vec.y;
                A_shared[threadIdx.y][threadIdx.x * 4 + 2] = a_vec.z;
                A_shared[threadIdx.y][threadIdx.x * 4 + 3] = a_vec.w;
            } else {
