                for (int i = 0; i < 4; ++i) {
                    if (A_load_col_start + i < N) {
                        A_shared[threadIdx.y][threadIdx.x * 4 + i] = A[A_row_global * N + A_load_col_start + i];
                    } else {
                        A_shared[threadIdx.y][threadIdx.x * 4 + i] = 0.0f;
                    }
                }
